const CATS = RAW.map(r=>[...r,null]).concat(RAW2.map(r=>[...r,"2026-10-17"])).map(([id,name,diff,list,from])=>{
  // Every answer has a fixed ID: its position in the list above. Answers you
  // approve on the site get IDs from 1000 up, so the two never clash.
  const entries = list.split(",").map((e,i)=>{const forms=e.split("|");return {idx:i,show:forms[0],forms:forms.map(norm).filter(Boolean)};});
  const byIdx = {}; entries.forEach(e=>byIdx[e.idx]=e);
  return {id,name,diff,entries,byIdx,from};
});
const CAT_BY_ID = Object.fromEntries(CATS.map(c=>[c.id,c]));

// Apply an owner decision from the database (approved answers only).
function applyApproval(d){
  const cat = CAT_BY_ID[d.category_id]; if(!cat || !d.word) return;
  if(d.maps_to != null){
    const e = cat.byIdx[d.maps_to]; if(e && !e.forms.includes(d.word)) e.forms.push(d.word);
  } else {
    const idx = 1000 + Number(d.id);
    if(cat.byIdx[idx]) return;
    const e = {idx, show:d.display || d.word, forms:[d.word], added:true};
    cat.entries.push(e); cat.byIdx[idx] = e;
  }
}

function lev(a,b,max){
  if(Math.abs(a.length-b.length)>max) return max+1;
  // Edit distance where swapping two neighbouring letters ("yrok") counts as one typo.
  let pp=null, prev=Array.from({length:b.length+1},(_,i)=>i);
  for(let i=1;i<=a.length;i++){
    const cur=[i]; let rowMin=i;
    for(let j=1;j<=b.length;j++){
      cur[j]=Math.min(prev[j]+1,cur[j-1]+1,prev[j-1]+(a[i-1]===b[j-1]?0:1));
      if(pp&&i>1&&j>1&&a[i-1]===b[j-2]&&a[i-2]===b[j-1]) cur[j]=Math.min(cur[j],pp[j-2]+1);
      if(cur[j]<rowMin) rowMin=cur[j];
    }
    if(rowMin>max) return max+1;
    pp=prev; prev=cur;
  }
  return prev[b.length];
}
// Returns the answer's ID or -1. Exact & plural first, then forgiving spelling.
function matchAnswer(cat,input){
  const n=norm(input); if(!n) return -1;
  const variants=[n]; if(n.endsWith("es")) variants.push(n.slice(0,-2)); if(n.endsWith("s")) variants.push(n.slice(0,-1)); variants.push(n+"s");
  for(let i=0;i<cat.entries.length;i++) for(const f of cat.entries[i].forms) if(variants.includes(f)) return cat.entries[i].idx;
  const tol = n.length<=4?0 : n.length<=7?1 : 2;
  if(!tol) return -1;
  let best=-1,bd=tol+1;
  for(let i=0;i<cat.entries.length;i++) for(const f of cat.entries[i].forms){
    if(f.length<=3) continue;
    const d=lev(n,f,tol); if(d<bd){bd=d;best=cat.entries[i].idx;}
  }
  return best;
}
// The closest answer to a word that didn't count, if it's near enough to be a
// misspelling (used for "Did you mean…?" and the owner's suggestions).
function nearestAnswer(cat,input,loose){
  const n=norm(input); if(n.length<3) return null;
  const max = loose ? Math.max(3,Math.ceil(n.length*0.5)) : (n.length<=5?2:n.length<=10?3:4);
  let best=null,bd=max+1;
  for(const e of cat.entries) for(const f of e.forms){
    if(f.length<3) continue;
    const d=lev(n,f,max);
    // On a tie, prefer the longer answer: more letters matched ("fohead" → Forehead, not Head).
    if(d<bd || (d===bd && best && d<=max && f.length > norm(best.show).length)){bd=d;best=e;}
    if(loose && f.length>=4 && (f.includes(n)||n.includes(f)) && bd>1){bd=1;best=e;}
  }
  return best;
}

